from .money import MAX_AMOUNT_CENTS, cents_to_decimal, format_amount, parse_amount_cents


def make_invoice(amounts):
    items = list(amounts)  # copy; the caller's list is never modified
    total_cents = 0
    for item in items:
        total_cents += parse_amount_cents(item)
    if total_cents > MAX_AMOUNT_CENTS:
        raise ValueError("total exceeds 1000000.00")
    return {"total": format_amount(cents_to_decimal(total_cents)), "count": len(items)}

