import re
from decimal import Decimal

MAX_AMOUNT_CENTS = 100_000_000  # 1000000.00

# Plain decimal: optional sign, digits, optional fraction. No whitespace, no exponent.
_PLAIN_DECIMAL = re.compile(r"[+-]?[0-9]+(?:\.[0-9]+)?")


def _decimal_to_cents(value):
    """Exact conversion of a finite Decimal to integer cents.

    Works on the digit tuple, so it never consults or modifies the decimal
    context and never rounds. Any nonzero digit below the cent position is
    rejected.
    """
    if not value.is_finite():
        raise ValueError("amount must be finite")
    if value.is_zero():
        raise ValueError("amount must be greater than zero")
    sign, digit_tuple, exp = value.as_tuple()
    if sign:
        raise ValueError("amount must be positive")

    digits = list(digit_tuple)  # coefficient, no leading zeros for nonzero values
    # value is in [10**(len(digits)+exp-1), 10**(len(digits)+exp)); this bound
    # rejects anything >= 10**7 before any large arithmetic happens.
    if len(digits) + exp >= 8:
        raise ValueError("amount exceeds 1000000.00")

    # Drop trailing zeros that lie below the cent position (e.g. "1.500").
    while digits and digits[-1] == 0 and exp < -2:
        digits.pop()
        exp += 1
    if exp < -2:
        raise ValueError("amount is not exactly representable in cents")

    cents = int("".join(map(str, digits))) * 10 ** (exp + 2)
    if cents > MAX_AMOUNT_CENTS:
        raise ValueError("amount exceeds 1000000.00")
    return cents


def parse_amount_cents(value):
    """Validate an amount and return it as an integer number of cents (1..100000000)."""
    if isinstance(value, bool):
        raise ValueError("bool is not a valid amount")
    if isinstance(value, Decimal):
        number = value
    elif isinstance(value, int):
        number = Decimal(value)  # exact; the constructor ignores the context
    elif isinstance(value, str):
        if _PLAIN_DECIMAL.fullmatch(value) is None:
            raise ValueError(f"not a plain decimal string: {value!r}")
        number = Decimal(value)  # exact; the constructor ignores the context
    else:
        raise ValueError(f"unsupported amount type: {type(value).__name__}")
    return _decimal_to_cents(number)


def cents_to_decimal(cents):
    """Return integer cents as a Decimal with exponent -2."""
    return Decimal(f"{cents // 100}.{cents % 100:02d}")


def parse_amount(value):
    return cents_to_decimal(parse_amount_cents(value))


def format_amount(value):
    return format(value, ".2f")
